const n="// 方案 A（修正）：不依赖浏览器全局标识符，使用脚本作用域共享 _actions 列表，使用 $h() 与 $data()，变更时调用 $rebindRules()\r\n\r\n// 共享的 action 列表（在同一个脚本模块内共享闭包）\r\nconst _actions = []\r\n\r\n// 内部注册函数：返回注销函数\r\nfunction _registerAction(id, vnode) {\r\n  if (!_actions.find(a => a.id === id)) {\r\n    _actions.push({ id, vnode })\r\n    // 通知页面重新绑定规则以刷新界面\r\n    $rebindRules()\r\n  }\r\n  return () => {\r\n    const idx = _actions.findIndex(a => a.id === id)\r\n    if (idx !== -1) {\r\n      _actions.splice(idx, 1)\r\n      $rebindRules()\r\n    }\r\n  }\r\n}\r\n\r\n// Render 函数：表格 + toolbar（toolbar 直接渲染 _actions 中的 vnode）\r\nregisterFunction('RenderTableWithToolbar', function() {\r\n  return function renderTableWithToolbar() {\r\n    const h = $h()\r\n    const data = $data()\r\n\r\n    const cols = [\r\n      h('el-table-column', { prop: 'id', label: 'ID', width: '100' }),\r\n      h('el-table-column', { prop: 'name', label: '姓名' })\r\n    ]\r\n\r\n    // toolbar 直接包含 actions 的 vnode（不会被额外包裹）\r\n    const toolbarInner = _actions.map(a => a.vnode)\r\n\r\n    // 调试：可见文本显示已注册 action ids（便于页面上直接确认）\r\n    const debugSpan = h('span', { style: { color: '#999', fontSize: '12px', marginLeft: '8px' } }, `actions: ${_actions.map(a => a.id).join(',')}`)\r\n\r\n    const toolbar = h('div', { class: 'table-toolbar', style: { padding: '8px', display: 'flex', alignItems: 'center' } }, [...toolbarInner, debugSpan])\r\n\r\n    // 调试日志：列出当前已注册的 action id\r\n    try { console.log('🧾 RenderTableWithToolbar actions:', _actions.map(a => a.id)) } catch (e) {}\r\n    // 为确保显示（el-table 并不一定支持 append slot），先渲染 toolbar，然后渲染表格\r\n    return h('div', [\r\n      toolbar,\r\n      h('el-table', { data: data.rows || [] }, {\r\n        default: () => cols\r\n      })\r\n    ])\r\n  }\r\n})\r\n\r\n// 子组件：在模块执行时注册一个按钮（保证在初次渲染前就存在）\r\nregisterFunction('RenderChildButton', function() {\r\n  // 在模块执行时直接创建并注册 action\r\n  try {\r\n    const h = $h()\r\n    const vnode = h('el-button', { type: 'primary', onClick: () => ElMessage.info('子组件按钮点击') }, '子组件按钮')\r\n    const unregister = _registerAction('child-button', vnode)\r\n    console.log('🔧 RenderChildButton module-registered:', _actions.map(a => a.id))\r\n\r\n    // 返回空渲染函数（子组件不在本地渲染任何 DOM）\r\n    return function renderChildButton() {\r\n      return null\r\n    }\r\n  } catch (e) {\r\n    console.error('❌ RenderChildButton registration failed:', e)\r\n    return function renderChildButton() { return null }\r\n  }\r\n})\r\n";export{n as default};
